import React from 'react';
import { Link, useLocation } from 'react-router-dom';
import { getUser } from '../../utils/auth';

const Sidebar = ({ onClose }) => {
  const location = useLocation();
  const user = getUser();

  const isActive = (path) => location.pathname === path;

  const handleLinkClick = () => {
    if (onClose) onClose();
  };

  const getMenuItems = () => {
    if (!user) return [];

    const baseItems = [
      { 
        name: 'Dashboard', 
        path: '/user/dashboard', 
        icon: '🏠',
        description: 'Overview & Quick Actions'
      },
      { 
        name: 'Buat Booking', 
        path: '/user/booking', 
        icon: '➕',
        description: 'Buat booking ruangan baru'
      },
      { 
        name: 'Booking Saya', 
        path: '/user/mybookings', 
        icon: '📋',
        description: 'Lihat semua booking Anda'
      }
    ];

    if (user.role === 'admin') {
      return [
        { 
          name: 'Admin Dashboard', 
          path: '/admin/dashboard', 
          icon: '👑',
          description: 'Admin overview & analytics'
        },
        { 
          name: 'Kelola Booking', 
          path: '/admin/bookings', 
          icon: '📊',
          description: 'Manage all bookings'
        },
        { 
          name: 'Kelola Ruangan', 
          path: '/admin/rooms', 
          icon: '🏢',
          description: 'Manage rooms & facilities'
        },
        { 
          name: 'Kelola Users', 
          path: '/admin/users', 
          icon: '👥',
          description: 'Manage user accounts'
        },
        { 
          name: 'Kelola Zoom', 
          path: '/admin/zoom', 
          icon: '💻',
          description: 'Manage Zoom settings'
        },
        ...baseItems
      ];
    }

    if (user.role === 'zoom_approver') {
      return [
        { 
          name: 'Zoom Dashboard', 
          path: '/zoom/dashboard', 
          icon: '💻',
          description: 'Zoom approval overview'
        },
        { 
          name: 'Zoom Requests', 
          path: '/zoom/requests', 
          icon: '📝',
          description: 'Approve Zoom requests'
        },
        ...baseItems
      ];
    }

    if (user.role === 'room_approver') {
      return [
        { 
          name: 'Room Dashboard', 
          path: '/room/dashboard', 
          icon: '🏢',
          description: 'Room approval overview'
        },
        { 
          name: 'Room Requests', 
          path: '/room/requests', 
          icon: '📝',
          description: 'Approve room requests'
        },
        { 
          name: 'Kelola Ruangan', 
          path: '/logistik/rooms', 
          icon: '🏢',
          description: 'Manage room facilities'
        },
        ...baseItems
      ];
    }

    return baseItems;
  };

  const getRoleInfo = () => {
    const roleMap = {
      admin: { 
        label: 'Administrator', 
        color: 'bg-purple-500', 
        lightColor: 'bg-purple-50',
        textColor: 'text-purple-700',
        icon: '👑' 
      },
      zoom_approver: { 
        label: 'Zoom Approver', 
        color: 'bg-blue-500', 
        lightColor: 'bg-blue-50',
        textColor: 'text-blue-700',
        icon: '💻' 
      },
      room_approver: { 
        label: 'Room Approver', 
        color: 'bg-green-500', 
        lightColor: 'bg-green-50',
        textColor: 'text-green-700',
        icon: '🏢' 
      },
      user: { 
        label: 'User', 
        color: 'bg-gray-500', 
        lightColor: 'bg-gray-50',
        textColor: 'text-gray-700',
        icon: '👤' 
      }
    };
    return roleMap[user?.role] || roleMap.user;
  };

  const getDisplayName = () => {
    if (user?.name) return user.name;
    if (user?.email) return user.email.split('@')[0];
    return 'User';
  };

  const menuItems = getMenuItems();
  const roleInfo = getRoleInfo();

  return (
    <div className="h-full bg-white border-r border-gray-200 flex flex-col">
      {/* User Info Header */}
      <div className={`${roleInfo.color} p-6 text-white`}>
        <div className="flex items-center space-x-4">
          <div className="w-12 h-12 bg-white bg-opacity-20 rounded-xl flex items-center justify-center">
            <span className="text-2xl">{roleInfo.icon}</span>
          </div>
          <div className="min-w-0 flex-1">
            <h2 className="text-lg font-semibold truncate">
              {getDisplayName()}
            </h2>
            <p className="text-sm opacity-90 truncate">
              {user?.email}
            </p>
            <div className="mt-2">
              <span className="inline-flex items-center px-2 py-1 rounded-full text-xs font-medium bg-white bg-opacity-20 text-white">
                {roleInfo.label}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Quick Stats */}
      <div className="p-4 bg-gray-50 border-b border-gray-200">
        <div className="grid grid-cols-2 gap-3">
          <div className="text-center">
            <div className="text-lg font-bold text-blue-600">12</div>
            <div className="text-xs text-gray-500">Total Bookings</div>
          </div>
          <div className="text-center">
            <div className="text-lg font-bold text-green-600">8</div>
            <div className="text-xs text-gray-500">Active</div>
          </div>
        </div>
      </div>

      {/* Navigation Menu */}
      <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
        <div className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-4">
          Navigation Menu
        </div>
        
        {menuItems.map((item) => (
          <Link
            key={item.path}
            to={item.path}
            onClick={handleLinkClick}
            className={`
              group flex items-start space-x-3 p-3 rounded-xl transition-all duration-200
              ${isActive(item.path)
                ? `${roleInfo.lightColor} ${roleInfo.textColor} shadow-sm border-l-4 ${roleInfo.color.replace('bg-', 'border-')}`
                : 'text-gray-700 hover:bg-gray-50 hover:text-gray-900'
              }
            `}
          >
            <div className={`
              w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 transition-all duration-200
              ${isActive(item.path)
                ? `${roleInfo.color} text-white shadow-sm`
                : 'bg-gray-100 group-hover:bg-gray-200'
              }
            `}>
              <span className="text-lg group-hover:scale-110 transition-transform">
                {item.icon}
              </span>
            </div>
            
            <div className="min-w-0 flex-1">
              <div className={`
                font-semibold text-sm
                ${isActive(item.path) ? roleInfo.textColor : 'text-gray-900'}
              `}>
                {item.name}
              </div>
              <div className="text-xs text-gray-500 mt-1 leading-tight">
                {item.description}
              </div>
            </div>
            
            {isActive(item.path) && (
              <div className={`w-2 h-2 ${roleInfo.color} rounded-full mt-2 flex-shrink-0`}></div>
            )}
          </Link>
        ))}
      </nav>

      {/* Quick Actions */}
      <div className="p-4 border-t border-gray-200 bg-gray-50">
        <div className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-3">
          Quick Actions
        </div>
        
        <div className="space-y-2">
          <Link
            to="/user/booking"
            onClick={handleLinkClick}
            className="w-full flex items-center space-x-2 px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 6v6m0 0v6m0-6h6m-6 0H6" />
            </svg>
            <span>New Booking</span>
          </Link>
          
          <Link
            to="/user/profile"
            onClick={handleLinkClick}
            className="w-full flex items-center space-x-2 px-3 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 text-sm font-medium rounded-lg transition-colors"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
            </svg>
            <span>Profile</span>
          </Link>
        </div>
      </div>

      {/* Footer */}
      <div className="p-4 border-t border-gray-200">
        <div className="text-center">
          <div className="text-xs text-gray-500">
